# Transform for task-4faf3061
# Rule: Expand frame of 1s, fill interior with 3 except center which stays 0

def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find bounding box of all 1s
    ones = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 1]
    if not ones:
        return grid

    min_r, max_r = min(r for r, c in ones), max(r for r, c in ones)
    min_c, max_c = min(c for r, c in ones), max(c for r, c in ones)

    # Build output
    output = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                output[r][c] = 1
            elif min_r + 1 <= r <= max_r - 1 and min_c + 1 <= c <= max_c - 1:
                # Interior of frame
                center_r = min_r + (max_r - min_r + 1) // 2
                center_c = min_c + (max_c - min_c + 1) // 2
                if (r, c) == (center_r, center_c):
                    output[r][c] = 0
                else:
                    output[r][c] = 3
            elif any(abs(r - nr) <= 1 and abs(c - nc) <= 1 for nr, nc in ones):
                # Expanded frame
                output[r][c] = 2
            else:
                output[r][c] = 0

    return output

